CREATE OR REPLACE FUNCTION public.accept_and_finalize_bulk_deck_analysis_attempt_v2(p_request_id uuid, p_user_id uuid, p_lease_token uuid, p_accepted_result jsonb, p_result_hash text, p_schema_version text, p_provider_model text, p_commander_oracle_id uuid, p_commander_name text, p_commander_art_uri text, p_report_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  request_row public.bulk_deck_analysis_requests;
  attempt_row public.bulk_deck_analysis_attempts;
  aggregate_row public.bulk_deck_analysis_monthly_usage;
  accept_time timestamptz := clock_timestamp();
  shell_value text;
  strategy_value text;
begin
  p_result_hash := btrim(coalesce(p_result_hash, ''));
  p_schema_version := btrim(coalesce(p_schema_version, ''));
  p_provider_model := btrim(coalesce(p_provider_model, ''));
  p_commander_name := btrim(coalesce(p_commander_name, ''));
  p_commander_art_uri := nullif(btrim(coalesce(p_commander_art_uri, '')), '');

  if p_accepted_result is null
     or jsonb_typeof(p_accepted_result) <> 'object'
     or octet_length(p_accepted_result::text) > 65536
     or p_accepted_result ->> 'schemaVersion' <> 'bda.accepted-result.v1' then
    raise exception 'BULK_ANALYSIS_RESULT_INVALID' using errcode = '22023';
  end if;
  if p_result_hash !~ '^sha256:[0-9a-f]{64}$' then
    raise exception 'BULK_ANALYSIS_RESULT_HASH_INVALID' using errcode = '22023';
  end if;
  if p_schema_version <> 'bda.accepted-result.v1' then
    raise exception 'BULK_ANALYSIS_SCHEMA_VERSION_UNSUPPORTED' using errcode = '22023';
  end if;
  if p_commander_oracle_id is null then
    raise exception 'BULK_ANALYSIS_COMMANDER_ORACLE_ID_REQUIRED' using errcode = '22023';
  end if;
  if p_report_payload is null
     or jsonb_typeof(p_report_payload) <> 'object'
     or octet_length(p_report_payload::text) > 131072
     or p_report_payload ->> 'schemaVersion' <> 'bda.saved-report.v1'
     or p_report_payload -> 'acceptedResult' is distinct from p_accepted_result then
    raise exception 'BULK_ANALYSIS_SAVED_REPORT_PAYLOAD_INVALID' using errcode = '22023';
  end if;

  shell_value := p_accepted_result #>> '{result,shell,band}';
  strategy_value := btrim(coalesce(
    p_accepted_result #>> '{result,thesis,primaryStrategy}', ''
  ));

  select * into request_row
  from public.bulk_deck_analysis_requests requests
  where requests.id = p_request_id
  for update;
  if request_row.id is null then
    raise exception 'BULK_ANALYSIS_REQUEST_NOT_FOUND' using errcode = 'P0002';
  end if;
  if request_row.user_id <> p_user_id then
    raise exception 'BULK_ANALYSIS_REQUEST_USER_MISMATCH' using errcode = '42501';
  end if;

  select * into attempt_row
  from public.bulk_deck_analysis_attempts attempts
  where attempts.request_id = p_request_id
  for update;
  if attempt_row.request_id is null then
    raise exception 'BULK_ANALYSIS_ATTEMPT_NOT_FOUND' using errcode = 'P0002';
  end if;

  if request_row.status = 'completed'
     and attempt_row.attempt_status = 'accepted' then
    if attempt_row.lease_token = p_lease_token
       and attempt_row.accepted_result_hash = p_result_hash
       and attempt_row.accepted_result = p_accepted_result
       and attempt_row.result_schema_version = p_schema_version
       and attempt_row.provider_model = p_provider_model then
      return jsonb_build_object(
        'result', 'accepted',
        'request_id', p_request_id,
        'accepted_result', attempt_row.accepted_result,
        'accepted_result_hash', attempt_row.accepted_result_hash,
        'result_schema_version', attempt_row.result_schema_version,
        'accepted_at', attempt_row.accepted_at,
        'retained_until', attempt_row.retained_until,
        'is_duplicate', true
      );
    end if;
    raise exception 'BULK_ANALYSIS_ACCEPT_CONFLICT' using errcode = 'P0001';
  end if;

  if request_row.status <> 'processing' then
    raise exception 'BULK_ANALYSIS_REQUEST_TERMINAL_%', upper(request_row.status)
      using errcode = 'P0001';
  end if;
  if request_row.expires_at <= accept_time then
    raise exception 'BULK_ANALYSIS_RESERVATION_EXPIRED' using errcode = 'P0001';
  end if;
  if attempt_row.attempt_status <> 'claimed'
     or attempt_row.provider_attempt_count <> 1 then
    raise exception 'BULK_ANALYSIS_ATTEMPT_NOT_CLAIMED' using errcode = 'P0001';
  end if;
  if attempt_row.lease_token <> p_lease_token then
    raise exception 'BULK_ANALYSIS_LEASE_TOKEN_MISMATCH' using errcode = '42501';
  end if;
  if attempt_row.lease_expires_at <= accept_time then
    raise exception 'BULK_ANALYSIS_LEASE_EXPIRED' using errcode = 'P0001';
  end if;

  select * into aggregate_row
  from public.bulk_deck_analysis_monthly_usage usage
  where usage.user_id = request_row.user_id
    and usage.usage_month = request_row.reservation_month
  for update;
  if aggregate_row.user_id is null then
    raise exception 'BULK_ANALYSIS_USAGE_AGGREGATE_MISSING' using errcode = 'P0001';
  end if;

  insert into public.bulk_deck_analysis_saved_reports (
    user_id,
    commander_oracle_id,
    commander_name,
    commander_art_uri,
    shell_strength,
    primary_strategy,
    analysis_completed_at,
    source_request_id,
    accepted_result_hash,
    accepted_result_schema_version,
    report_payload,
    created_at,
    updated_at
  )
  values (
    request_row.user_id,
    p_commander_oracle_id,
    p_commander_name,
    p_commander_art_uri,
    shell_value,
    strategy_value,
    accept_time,
    p_request_id,
    p_result_hash,
    p_schema_version,
    p_report_payload,
    accept_time,
    accept_time
  )
  on conflict on constraint
    bulk_deck_analysis_saved_reports_user_commander_unique
  do update set
    commander_name = excluded.commander_name,
    commander_art_uri = excluded.commander_art_uri,
    shell_strength = excluded.shell_strength,
    primary_strategy = excluded.primary_strategy,
    analysis_completed_at = excluded.analysis_completed_at,
    source_request_id = excluded.source_request_id,
    accepted_result_hash = excluded.accepted_result_hash,
    accepted_result_schema_version = excluded.accepted_result_schema_version,
    report_payload = excluded.report_payload,
    updated_at = excluded.updated_at
  where exists (
    select 1
    from public.bulk_deck_analysis_requests prior
    where prior.id =
      bulk_deck_analysis_saved_reports.source_request_id
      and (prior.reserved_at, prior.id) <
        (request_row.reserved_at, request_row.id)
  );

  update public.bulk_deck_analysis_attempts
  set attempt_status = 'accepted',
      provider_finished_at = accept_time,
      provider_model = p_provider_model,
      provider_outcome_code = 'ACCEPTED',
      accepted_result = p_accepted_result,
      accepted_result_hash = p_result_hash,
      result_schema_version = p_schema_version,
      accepted_at = accept_time,
      retained_until = accept_time + interval '7 days'
  where request_id = p_request_id;

  update public.bulk_deck_analysis_monthly_usage
  set completed_count = completed_count + 1
  where user_id = request_row.user_id
    and usage_month = request_row.reservation_month;

  update public.bulk_deck_analysis_requests
  set status = 'completed',
      completed_at = accept_time,
      terminal_code = 'COMPLETED'
  where id = p_request_id;

  return jsonb_build_object(
    'result', 'accepted',
    'request_id', p_request_id,
    'accepted_result', p_accepted_result,
    'accepted_result_hash', p_result_hash,
    'result_schema_version', p_schema_version,
    'accepted_at', accept_time,
    'retained_until', accept_time + interval '7 days',
    'is_duplicate', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.adjust_user_token_balance(target_user_id uuid, amount integer)
 RETURNS user_token_wallets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  wallet public.user_token_wallets;
begin
  if public.current_user_role() not in ('Admin', 'SuperAdmin') then
    raise exception 'Only Admin or SuperAdmin can adjust token balances.'
      using errcode = '42501';
  end if;

  if target_user_id is null then
    raise exception 'Target user is required.'
      using errcode = '23502';
  end if;

  if amount is null then
    raise exception 'Adjustment amount is required.'
      using errcode = '23502';
  end if;

  perform public.ensure_user_token_wallet(target_user_id);

  update public.user_token_wallets
  set token_balance = token_balance + amount
  where user_id = target_user_id
    and token_balance + amount >= 0
  returning * into wallet;

  if wallet.user_id is null then
    raise exception 'Adjustment cannot make token balance negative.'
      using errcode = '22023';
  end if;

  return wallet;
end;
$function$

CREATE OR REPLACE FUNCTION public.bulk_deck_analysis_resolve_entitlement(p_user_id uuid, p_session_id uuid)
 RETURNS TABLE(eligible boolean, entitlement_source text, monthly_limit integer, is_unlimited boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  profile_role public.app_role;
  store_entitlement public.user_entitlements;
  sanctum_entitlement public.user_entitlements;
  has_store_owner boolean := false;
  has_sanctum boolean := false;
  has_beta boolean := false;
begin
  select role into profile_role
  from public.profiles
  where user_id = p_user_id;

  if profile_role = 'SuperAdmin' then
    return query select true, 'superadmin'::text, null::integer, true;
    return;
  end if;

  select * into store_entitlement
  from public.user_entitlements
  where user_id = p_user_id and entitlement_key = 'store_owner'
  limit 1;

  if store_entitlement.id is not null then
    has_store_owner :=
      store_entitlement.status in ('active', 'trialing', 'grace_period')
      or (
        store_entitlement.status = 'cancelled'
        and store_entitlement.current_period_end is not null
        and store_entitlement.current_period_end > clock_timestamp()
      );
  end if;

  if has_store_owner then
    return query select true, 'store_owner'::text, 10, false;
    return;
  end if;

  select * into sanctum_entitlement
  from public.user_entitlements
  where user_id = p_user_id and entitlement_key = 'sanctum'
  limit 1;

  if sanctum_entitlement.id is not null then
    has_sanctum :=
      sanctum_entitlement.status in ('active', 'trialing', 'grace_period')
      or (
        sanctum_entitlement.status = 'cancelled'
        and sanctum_entitlement.current_period_end is not null
        and sanctum_entitlement.current_period_end > clock_timestamp()
      );
  end if;

  if has_sanctum then
    entitlement_source := case sanctum_entitlement.source
      when 'admin' then 'admin_grant'
      when 'promo' then 'promo_grant'
      when 'gift' then 'gift_grant'
      when 'system' then 'system_grant'
      else 'paid_sanctum'
    end;
    return query select true, entitlement_source, 10, false;
    return;
  end if;

  if p_session_id is not null then
    select exists (
      select 1
      from public.sanctum_beta_grants grants
      join public.sanctum_beta_programs programs
        on programs.id = grants.program_id
      join public.sanctum_beta_testers testers
        on testers.program_id = grants.program_id
       and testers.user_id = grants.user_id
       and testers.revoked_at is null
      where grants.user_id = p_user_id
        and grants.session_id = p_session_id
        and grants.revoked_at is null
        and grants.expires_at > clock_timestamp()
        and programs.disabled_at is null
        and public.sanctum_beta_auth_session_is_active(p_user_id, p_session_id)
    ) into has_beta;
  end if;

  if has_beta then
    return query select true, 'beta_sanctum'::text, 30, false;
    return;
  end if;

  return query select false, 'free'::text, null::integer, false;
end;
$function$

CREATE OR REPLACE FUNCTION public.bulk_deck_analysis_usage_snapshot_for(p_user_id uuid, p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_month date := public.bulk_deck_analysis_month_utc();
  entitlement record;
  used_count integer := 0;
  reservation_count integer := 0;
  remaining_count integer;
begin
  perform public.bulk_deck_analysis_expire_stale(p_user_id, null);

  select * into entitlement
  from public.bulk_deck_analysis_resolve_entitlement(p_user_id, p_session_id)
  limit 1;

  select coalesce(usage.completed_count, 0)
  into used_count
  from public.bulk_deck_analysis_monthly_usage usage
  where usage.user_id = p_user_id and usage.usage_month = current_month;
  used_count := coalesce(used_count, 0);

  select count(*)::integer into reservation_count
  from public.bulk_deck_analysis_requests requests
  where requests.user_id = p_user_id
    and requests.reservation_month = current_month
    and requests.status = 'processing'
    and requests.expires_at > clock_timestamp();

  if entitlement.is_unlimited then
    remaining_count := null;
  elsif entitlement.eligible then
    remaining_count := greatest(
      entitlement.monthly_limit - used_count - reservation_count,
      0
    );
  else
    remaining_count := 0;
  end if;

  return jsonb_build_object(
    'eligible', entitlement.eligible,
    'used', used_count,
    'limit', entitlement.monthly_limit,
    'remaining', remaining_count,
    'active_reservations', reservation_count,
    'month_start', current_month,
    'next_reset', public.bulk_deck_analysis_next_reset_utc(current_month),
    'entitlement_source', entitlement.entitlement_source,
    'is_unlimited', entitlement.is_unlimited
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_bulk_deck_analysis_attempt(p_request_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  request_row public.bulk_deck_analysis_requests;
  attempt_row public.bulk_deck_analysis_attempts;
  claim_time timestamptz := clock_timestamp();
begin
  if p_request_id is null or p_user_id is null then
    raise exception 'BULK_ANALYSIS_CLAIM_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  select * into request_row
  from public.bulk_deck_analysis_requests requests
  where requests.id = p_request_id
  for update;
  if request_row.id is null then
    raise exception 'BULK_ANALYSIS_REQUEST_NOT_FOUND' using errcode = 'P0002';
  end if;
  if request_row.user_id <> p_user_id then
    raise exception 'BULK_ANALYSIS_REQUEST_USER_MISMATCH' using errcode = '42501';
  end if;

  select * into attempt_row
  from public.bulk_deck_analysis_attempts attempts
  where attempts.request_id = p_request_id
  for update;

  if attempt_row.request_id is not null then
    if attempt_row.attempt_status = 'accepted' then
      return jsonb_build_object('claim', 'completed', 'request_id', p_request_id);
    end if;
    if attempt_row.attempt_status in ('failed', 'unknown_outcome') then
      return jsonb_build_object(
        'claim', 'terminal', 'request_id', p_request_id,
        'attempt_status', attempt_row.attempt_status,
        'code', attempt_row.provider_outcome_code
      );
    end if;
    if attempt_row.lease_expires_at > claim_time then
      return jsonb_build_object(
        'claim', 'in_progress', 'request_id', p_request_id,
        'lease_expires_at', attempt_row.lease_expires_at
      );
    end if;

    update public.bulk_deck_analysis_attempts
    set attempt_status = 'unknown_outcome',
        provider_finished_at = claim_time,
        provider_outcome_code = 'PROVIDER_OUTCOME_UNKNOWN'
    where request_id = p_request_id
    returning * into attempt_row;

    if request_row.status = 'processing' then
      update public.bulk_deck_analysis_requests
      set status = 'failed', failed_at = claim_time,
          terminal_code = 'PROVIDER_OUTCOME_UNKNOWN'
      where id = p_request_id;
    end if;

    return jsonb_build_object(
      'claim', 'terminal', 'request_id', p_request_id,
      'attempt_status', 'unknown_outcome',
      'code', 'PROVIDER_OUTCOME_UNKNOWN'
    );
  end if;

  if request_row.status <> 'processing' then
    return jsonb_build_object(
      'claim', 'terminal', 'request_id', p_request_id,
      'request_status', request_row.status,
      'code', request_row.terminal_code
    );
  end if;
  if request_row.expires_at <= claim_time then
    update public.bulk_deck_analysis_requests
    set status = 'expired', expired_at = claim_time,
        terminal_code = 'RESERVATION_EXPIRED'
    where id = p_request_id;
    return jsonb_build_object(
      'claim', 'terminal', 'request_id', p_request_id,
      'request_status', 'expired', 'code', 'RESERVATION_EXPIRED'
    );
  end if;

  insert into public.bulk_deck_analysis_attempts (
    request_id, attempt_status, lease_token, lease_expires_at,
    provider_attempt_count, provider_started_at
  ) values (
    p_request_id, 'claimed', extensions.gen_random_uuid(),
    claim_time + interval '90 seconds', 1, claim_time
  ) returning * into attempt_row;

  return jsonb_build_object(
    'claim', 'granted', 'request_id', p_request_id,
    'lease_token', attempt_row.lease_token,
    'lease_expires_at', attempt_row.lease_expires_at,
    'provider_attempt_count', attempt_row.provider_attempt_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_connected_match_if_ready(p_session_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
begin
  if current_user_id is null then
    raise exception 'Authentication is required to complete a Connected Match.'
      using errcode = '28000';
  end if;

  if not exists (
    select 1
    from public.connected_match_participants participants
    where participants.session_id = p_session_id
      and participants.user_id = current_user_id
  ) then
    raise exception 'You are not part of this Connected Match.'
      using errcode = '42501';
  end if;

  return public.connected_match_complete_if_ready(p_session_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_player_store_onboarding()
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  updated_profile public.profiles;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.'
      using errcode = '28000';
  end if;

  if exists (
    select 1
    from public.profiles
    where user_id = auth.uid()
      and store_onboarding_completed
  ) then
    raise exception 'Store onboarding has already been completed.'
      using errcode = '23505';
  end if;

  update public.profiles
  set
    store_onboarding_completed = true,
    store_onboarding_choice = 'player',
    store_onboarding_completed_at = now()
  where user_id = auth.uid()
  returning * into updated_profile;

  if updated_profile.user_id is null then
    raise exception 'Profile not found.'
      using errcode = 'P0002';
  end if;

  return updated_profile;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_store_owner_onboarding(store_name text)
 RETURNS stores
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  trimmed_name text := nullif(btrim(store_name), '');
  base_slug text;
  candidate_slug text;
  suffix integer := 1;
  created_store public.stores;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.'
      using errcode = '28000';
  end if;

  if trimmed_name is null or length(trimmed_name) < 2 then
    raise exception 'Store name is required.'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.profiles
    where user_id = auth.uid()
      and store_onboarding_completed
  ) then
    raise exception 'Store onboarding has already been completed.'
      using errcode = '23505';
  end if;

  base_slug := public.store_slug_base(trimmed_name);

  if length(base_slug) < 3 then
    base_slug := 'store-' || substr(replace(auth.uid()::text, '-', ''), 1, 8);
  end if;

  base_slug := substr(base_slug, 1, 56);
  candidate_slug := base_slug;

  while exists (
    select 1
    from public.stores
    where slug = candidate_slug
  ) loop
    suffix := suffix + 1;
    candidate_slug := substr(base_slug, 1, 56) || '-' || suffix::text;
  end loop;

  insert into public.stores (
    owner_id,
    name,
    slug,
    is_public,
    is_active
  )
  values (
    auth.uid(),
    trimmed_name,
    candidate_slug,
    false,
    false
  )
  returning * into created_store;

  insert into public.store_staff (
    store_id,
    user_id,
    role,
    is_active,
    invited_by
  )
  values (
    created_store.id,
    auth.uid(),
    'owner',
    true,
    auth.uid()
  )
  on conflict (store_id, user_id)
  do update set
    role = 'owner',
    is_active = true,
    invited_by = auth.uid();

  update public.profiles
  set
    role = 'StoreOwner',
    store_onboarding_completed = true,
    store_onboarding_choice = 'store_owner',
    store_onboarding_completed_at = now()
  where user_id = auth.uid();

  return created_store;
end;
$function$

CREATE OR REPLACE FUNCTION public.connected_match_build_player_payload(p_player jsonb, p_user_id uuid)
 RETURNS TABLE(display_name text, avatar_ref text, commander_name text, commander_scryfall_id text, commander_image_url text, commander_art_crop_url text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  profile_record public.profiles;
begin
  select *
  into profile_record
  from public.profiles
  where user_id = p_user_id;

  display_name :=
    nullif(btrim(p_player ->> 'display_name'), '');

  if display_name is null then
    display_name :=
      nullif(btrim(coalesce(profile_record.display_name, '')), '');
  end if;

  if display_name is null then
    display_name :=
      nullif(btrim(coalesce(profile_record.username_display, '')), '');
  end if;

  if display_name is null then
    display_name := 'Player';
  end if;

  avatar_ref :=
    coalesce(nullif(btrim(p_player ->> 'avatar_ref'), ''), 'deck_sage_default');

  if avatar_ref !~ '^[a-zA-Z0-9_-]{3,80}$' then
    avatar_ref := 'deck_sage_default';
  end if;

  commander_name := nullif(btrim(p_player ->> 'commander_name'), '');
  commander_scryfall_id := nullif(btrim(p_player ->> 'commander_scryfall_id'), '');
  commander_image_url := nullif(btrim(p_player ->> 'commander_image_url'), '');
  commander_art_crop_url := nullif(btrim(p_player ->> 'commander_art_crop_url'), '');

  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.connected_match_complete_if_ready(p_session_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  session_record public.connected_match_sessions;
  active_count integer;
  total_count integer;
  winner_count integer;
  winner_record public.connected_match_participants;
  selected_winner_participant_id uuid;
  selected_winner_user_id uuid;
  participant_user_ids uuid[];
  final_result_status text := 'completed';
begin
  select *
  into session_record
  from public.connected_match_sessions sessions
  where sessions.id = p_session_id
  for update;

  if session_record.id is null or session_record.status <> 'active' then
    return false;
  end if;

  select
    count(*) filter (where participants.terminal_state = 'active'),
    count(*),
    count(*) filter (where participants.terminal_state = 'won')
  into active_count, total_count, winner_count
  from public.connected_match_participants participants
  where participants.session_id = p_session_id;

  if total_count = 0 then
    return false;
  end if;

  if winner_count = 1 then
    select *
    into winner_record
    from public.connected_match_participants participants
    where participants.session_id = p_session_id
      and participants.terminal_state = 'won'
    order by participants.updated_at asc
    limit 1;

    selected_winner_participant_id := winner_record.id;
    selected_winner_user_id := winner_record.user_id;
  elsif winner_count > 1 then
    final_result_status := 'completed_unresolved_multiple_winners';
  elsif active_count = 1 then
    select *
    into winner_record
    from public.connected_match_participants participants
    where participants.session_id = p_session_id
      and participants.terminal_state = 'active'
    limit 1;

    update public.connected_match_participants
    set
      terminal_state = 'won',
      elimination_reason = null
    where id = winner_record.id;

    winner_count := 1;
    selected_winner_participant_id := winner_record.id;
    selected_winner_user_id := winner_record.user_id;
  elsif active_count > 0 then
    return false;
  else
    final_result_status := 'completed_no_winner_all_terminal';
  end if;

  select array_agg(participants.user_id order by participants.seat_index)
  into participant_user_ids
  from public.connected_match_participants participants
  where participants.session_id = p_session_id;

  update public.connected_match_sessions
  set
    status = 'completed',
    winner_participant_id = selected_winner_participant_id,
    completed_at = now()
  where id = p_session_id;

  insert into public.connected_game_history (
    session_id,
    participant_user_ids,
    game_started_at,
    game_completed_at,
    participants,
    commanders,
    winner_user_id,
    winner_participant_id,
    final_result,
    left_mid_game
  )
  values (
    p_session_id,
    participant_user_ids,
    session_record.started_at,
    now(),
    public.connected_match_participant_snapshot(p_session_id),
    public.connected_match_commander_snapshot(p_session_id),
    selected_winner_user_id,
    selected_winner_participant_id,
    jsonb_build_object(
      'status', final_result_status,
      'winner_participant_id', selected_winner_participant_id,
      'winner_user_id', selected_winner_user_id,
      'winner_count', winner_count
    ),
    coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'participant_id', participants.id,
          'user_id', participants.user_id,
          'display_name', participants.display_name
        )
        order by participants.seat_index
      )
      from public.connected_match_participants participants
      where participants.session_id = p_session_id
        and participants.left_mid_game
    ), '[]'::jsonb)
  )
  on conflict (session_id) do nothing;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.connected_match_snapshot(p_session_id uuid)
 RETURNS TABLE(session jsonb, participants jsonb, commander_damage jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
begin
  if current_user_id is null then
    raise exception 'Authentication is required to view a Connected Match.'
      using errcode = '28000';
  end if;

  if not exists (
    select 1
    from public.connected_match_participants viewer
    where viewer.session_id = p_session_id
      and viewer.user_id = current_user_id
  ) then
    raise exception 'You are not part of this Connected Match.'
      using errcode = '42501';
  end if;

  select row_to_json(sessions)::jsonb
  into session
  from public.connected_match_sessions sessions
  where sessions.id = p_session_id;

  select coalesce(
    jsonb_agg(
      participant_rows.participant_json
      order by participant_rows.seat_index
    ),
    '[]'::jsonb
  )
  into participants
  from (
    select
      to_jsonb(p) as participant_json,
      p.seat_index
    from public.connected_match_participants as p
    where p.session_id = p_session_id
  ) as participant_rows;

  select coalesce(
    jsonb_agg(damage_rows.damage_json),
    '[]'::jsonb
  )
  into commander_damage
  from (
    select to_jsonb(d) as damage_json
    from public.connected_match_commander_damage as d
    where d.session_id = p_session_id
  ) as damage_rows;

  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_store_lfg_interest(p_store_id uuid, p_requesting_checkin_id uuid)
 RETURNS TABLE(ok boolean, already_recorded boolean, interest_id uuid, store_id uuid, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  checkin_date date := (now() at time zone 'utc')::date;
  active_store_id uuid;
  requesting_checkin record;
  responding_checkin record;
  inserted_interest record;
  existing_interest record;
  low_user_id uuid;
  high_user_id uuid;
begin
  if current_user_id is null then
    raise exception 'Authentication is required to respond to a Commander Beacon.'
      using errcode = '28000';
  end if;

  select stores.id
  into active_store_id
  from public.stores
  where stores.id = p_store_id
    and stores.is_public
    and stores.is_active;

  if active_store_id is null then
    raise exception 'This store check-in link is no longer active.'
      using errcode = 'P0002';
  end if;

  select store_checkins.id, store_checkins.user_id
  into requesting_checkin
  from public.store_checkins
  where store_checkins.id = p_requesting_checkin_id
    and store_checkins.store_id = active_store_id
    and store_checkins.check_in_date = checkin_date
    and store_checkins.looking_for_commander_game
    and store_checkins.commander_game_status = 'looking';

  if requesting_checkin.id is null then
    raise exception 'That Commander Beacon is no longer active.'
      using errcode = 'P0002';
  end if;

  if requesting_checkin.user_id = current_user_id then
    raise exception 'You cannot respond to your own Commander Beacon.'
      using errcode = '22023';
  end if;

  select store_checkins.id, store_checkins.user_id
  into responding_checkin
  from public.store_checkins
  where store_checkins.store_id = active_store_id
    and store_checkins.user_id = current_user_id
    and store_checkins.check_in_date = checkin_date
    and store_checkins.looking_for_commander_game
    and store_checkins.commander_game_status = 'looking';

  if responding_checkin.id is null then
    raise exception 'Mark yourself as looking for Commander before responding.'
      using errcode = '42501';
  end if;

  low_user_id := least(requesting_checkin.user_id, current_user_id);
  high_user_id := greatest(requesting_checkin.user_id, current_user_id);

  insert into public.store_lfg_interest (
    store_id,
    requesting_user_id,
    responding_user_id,
    interest_date,
    pair_low_user_id,
    pair_high_user_id
  )
  values (
    active_store_id,
    requesting_checkin.user_id,
    current_user_id,
    checkin_date,
    low_user_id,
    high_user_id
  )
  on conflict (store_id, pair_low_user_id, pair_high_user_id, interest_date) do nothing
  returning id, store_lfg_interest.store_id, store_lfg_interest.created_at
  into inserted_interest;

  if inserted_interest.id is not null then
    return query
    select
      true,
      false,
      inserted_interest.id,
      inserted_interest.store_id,
      inserted_interest.created_at;
    return;
  end if;

  select id, store_lfg_interest.store_id, store_lfg_interest.created_at
  into existing_interest
  from public.store_lfg_interest
  where store_lfg_interest.store_id = active_store_id
    and store_lfg_interest.pair_low_user_id = low_user_id
    and store_lfg_interest.pair_high_user_id = high_user_id
    and store_lfg_interest.interest_date = checkin_date
  limit 1;

  return query
  select
    true,
    true,
    existing_interest.id,
    existing_interest.store_id,
    existing_interest.created_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_store_token_wallet(p_store_id uuid)
 RETURNS store_token_wallets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  wallet public.store_token_wallets;
begin
  if not public.is_store_staff(p_store_id) then
    raise exception 'You are not authorized to read this store token wallet.'
      using errcode = '42501';
  end if;

  insert into public.store_token_wallets (store_id)
  values (p_store_id)
  on conflict (store_id) do nothing;

  select *
  into wallet
  from public.store_token_wallets
  where store_id = p_store_id;

  return wallet;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_user_token_wallet(target_user_id uuid DEFAULT auth.uid())
 RETURNS user_token_wallets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  wallet public.user_token_wallets;
begin
  if target_user_id is null then
    raise exception 'A signed-in user is required.'
      using errcode = '42501';
  end if;

  if target_user_id <> auth.uid()
    and public.current_user_role() not in ('Admin', 'SuperAdmin') then
    raise exception 'Only Admin or SuperAdmin can access another user wallet.'
      using errcode = '42501';
  end if;

  insert into public.user_token_wallets (user_id)
  values (target_user_id)
  on conflict (user_id) do nothing;

  select *
  into wallet
  from public.user_token_wallets
  where user_id = target_user_id;

  return wallet;
end;
$function$

CREATE OR REPLACE FUNCTION public.fail_bulk_deck_analysis_attempt(p_request_id uuid, p_user_id uuid, p_lease_token uuid, p_terminal_code text, p_attempt_status text DEFAULT 'failed'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  request_row public.bulk_deck_analysis_requests;
  attempt_row public.bulk_deck_analysis_attempts;
  finish_time timestamptz := clock_timestamp();
begin
  p_terminal_code := upper(btrim(coalesce(p_terminal_code, '')));
  p_attempt_status := lower(btrim(coalesce(p_attempt_status, '')));
  if p_attempt_status not in ('failed', 'unknown_outcome') then
    raise exception 'BULK_ANALYSIS_ATTEMPT_STATUS_INVALID' using errcode = '22023';
  end if;
  if length(p_terminal_code) not between 3 and 64
     or p_terminal_code !~ '^[A-Z0-9_]+$'
     or p_terminal_code in ('ACCEPTED', 'COMPLETED', 'RESERVATION_EXPIRED') then
    raise exception 'BULK_ANALYSIS_TERMINAL_CODE_INVALID' using errcode = '22023';
  end if;

  select * into request_row
  from public.bulk_deck_analysis_requests requests
  where requests.id = p_request_id
  for update;
  if request_row.id is null then
    raise exception 'BULK_ANALYSIS_REQUEST_NOT_FOUND' using errcode = 'P0002';
  end if;
  if request_row.user_id <> p_user_id then
    raise exception 'BULK_ANALYSIS_REQUEST_USER_MISMATCH' using errcode = '42501';
  end if;

  select * into attempt_row
  from public.bulk_deck_analysis_attempts attempts
  where attempts.request_id = p_request_id
  for update;
  if attempt_row.request_id is null then
    raise exception 'BULK_ANALYSIS_ATTEMPT_NOT_FOUND' using errcode = 'P0002';
  end if;
  if attempt_row.lease_token <> p_lease_token then
    raise exception 'BULK_ANALYSIS_LEASE_TOKEN_MISMATCH' using errcode = '42501';
  end if;

  if attempt_row.attempt_status in ('failed', 'unknown_outcome') then
    if attempt_row.attempt_status = p_attempt_status
       and attempt_row.provider_outcome_code = p_terminal_code
       and request_row.status = 'failed'
       and request_row.terminal_code = p_terminal_code then
      return jsonb_build_object(
        'result', 'terminal', 'request_id', p_request_id,
        'attempt_status', attempt_row.attempt_status,
        'code', attempt_row.provider_outcome_code,
        'is_duplicate', true
      );
    end if;
    raise exception 'BULK_ANALYSIS_TERMINAL_CONFLICT' using errcode = 'P0001';
  end if;
  if attempt_row.attempt_status = 'accepted' or request_row.status = 'completed' then
    raise exception 'BULK_ANALYSIS_ALREADY_COMPLETED' using errcode = 'P0001';
  end if;
  if request_row.status <> 'processing' then
    raise exception 'BULK_ANALYSIS_REQUEST_TERMINAL_%', upper(request_row.status)
      using errcode = 'P0001';
  end if;

  update public.bulk_deck_analysis_attempts
  set attempt_status = p_attempt_status,
      provider_finished_at = finish_time,
      provider_outcome_code = p_terminal_code
  where request_id = p_request_id;

  update public.bulk_deck_analysis_requests
  set status = 'failed', failed_at = finish_time,
      terminal_code = p_terminal_code
  where id = p_request_id;

  return jsonb_build_object(
    'result', 'terminal', 'request_id', p_request_id,
    'attempt_status', p_attempt_status, 'code', p_terminal_code,
    'is_duplicate', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.fail_bulk_deck_analysis_request(p_request_id uuid, p_terminal_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  request_row public.bulk_deck_analysis_requests;
begin
  p_terminal_code := upper(btrim(coalesce(p_terminal_code, '')));
  if length(p_terminal_code) not between 3 and 64
     or p_terminal_code !~ '^[A-Z0-9_]+$'
     or p_terminal_code in ('COMPLETED', 'RESERVATION_EXPIRED') then
    raise exception 'BULK_ANALYSIS_TERMINAL_CODE_INVALID' using errcode = '22023';
  end if;

  select * into request_row
  from public.bulk_deck_analysis_requests
  where id = p_request_id
  for update;
  if request_row.id is null then
    raise exception 'BULK_ANALYSIS_REQUEST_NOT_FOUND' using errcode = 'P0002';
  end if;
  if request_row.status = 'failed' then
    return public.bulk_deck_analysis_request_json(request_row);
  end if;
  if request_row.status <> 'processing' then
    raise exception 'BULK_ANALYSIS_REQUEST_TERMINAL_%', upper(request_row.status)
      using errcode = 'P0001';
  end if;
  if request_row.expires_at <= clock_timestamp() then
    update public.bulk_deck_analysis_requests
    set status = 'expired', expired_at = clock_timestamp(),
        terminal_code = 'RESERVATION_EXPIRED'
    where id = request_row.id
    returning * into request_row;
    return public.bulk_deck_analysis_request_json(request_row);
  end if;

  update public.bulk_deck_analysis_requests
  set status = 'failed', failed_at = clock_timestamp(),
      terminal_code = p_terminal_code
  where id = request_row.id
  returning * into request_row;
  return public.bulk_deck_analysis_request_json(request_row);
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_bulk_deck_analysis_request(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  request_row public.bulk_deck_analysis_requests;
  aggregate_row public.bulk_deck_analysis_monthly_usage;
begin
  select * into request_row
  from public.bulk_deck_analysis_requests
  where id = p_request_id
  for update;
  if request_row.id is null then
    raise exception 'BULK_ANALYSIS_REQUEST_NOT_FOUND' using errcode = 'P0002';
  end if;
  if request_row.status = 'completed' then
    return public.bulk_deck_analysis_request_json(request_row);
  end if;
  if request_row.status <> 'processing' then
    raise exception 'BULK_ANALYSIS_REQUEST_TERMINAL_%', upper(request_row.status)
      using errcode = 'P0001';
  end if;
  if request_row.expires_at <= clock_timestamp() then
    update public.bulk_deck_analysis_requests
    set status = 'expired', expired_at = clock_timestamp(),
        terminal_code = 'RESERVATION_EXPIRED'
    where id = request_row.id
    returning * into request_row;
    return public.bulk_deck_analysis_request_json(request_row);
  end if;

  select * into aggregate_row
  from public.bulk_deck_analysis_monthly_usage usage
  where usage.user_id = request_row.user_id
    and usage.usage_month = request_row.reservation_month
  for update;
  if aggregate_row.user_id is null then
    raise exception 'BULK_ANALYSIS_USAGE_AGGREGATE_MISSING' using errcode = 'P0001';
  end if;

  update public.bulk_deck_analysis_monthly_usage
  set completed_count = completed_count + 1
  where user_id = request_row.user_id
    and usage_month = request_row.reservation_month;

  update public.bulk_deck_analysis_requests
  set status = 'completed', completed_at = clock_timestamp(),
      terminal_code = 'COMPLETED'
  where id = request_row.id
  returning * into request_row;

  return public.bulk_deck_analysis_request_json(request_row);
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_connected_match_join_code()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  candidate text;
begin
  loop
    candidate := upper(substr(replace(extensions.gen_random_uuid()::text, '-', ''), 1, 8));

    if not exists (
      select 1
      from public.connected_match_sessions
      where join_code = candidate
    ) then
      return candidate;
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_account_deletion_job_checkpoint(p_request_id uuid, p_expected_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  job_row public.account_deletion_jobs;
  expected_fingerprint text;
begin
  if p_request_id is null or p_expected_user_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REQUEST',
      'retryable', false
    );
  end if;

  expected_fingerprint := encode(
    extensions.digest(p_expected_user_id::text, 'sha256'),
    'hex'
  );

  select jobs.*
  into job_row
  from public.account_deletion_jobs as jobs
  where jobs.request_id = p_request_id;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'DELETION_JOB_NOT_FOUND',
      'retryable', false
    );
  end if;

  if job_row.user_fingerprint <> expected_fingerprint then
    return jsonb_build_object(
      'ok', false,
      'code', 'IDEMPOTENCY_TARGET_MISMATCH',
      'retryable', false
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'code', 'DELETION_JOB_CHECKPOINT',
    'status', job_row.status,
    'databaseCleanedAt', job_row.database_cleaned_at,
    'providerCleanedAt', job_row.provider_cleaned_at,
    'authDeletedAt', job_row.auth_deleted_at,
    'completedAt', job_row.completed_at,
    'retryable', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_bulk_deck_analysis_phase4_result(p_request_id uuid DEFAULT NULL::uuid, p_idempotency_key uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  request_row public.bulk_deck_analysis_requests;
  attempt_row public.bulk_deck_analysis_attempts;
  recovery_time timestamptz := clock_timestamp();
begin
  if current_user_id is null then
    raise exception 'BULK_ANALYSIS_AUTH_REQUIRED' using errcode = '28000';
  end if;
  if (p_request_id is null) = (p_idempotency_key is null) then
    raise exception 'BULK_ANALYSIS_RESULT_IDENTITY_INVALID' using errcode = '22023';
  end if;

  select * into request_row
  from public.bulk_deck_analysis_requests requests
  where requests.user_id = current_user_id
    and ((p_request_id is not null and requests.id = p_request_id)
      or (p_idempotency_key is not null
        and requests.idempotency_key = p_idempotency_key))
  for update;
  if request_row.id is null then
    raise exception 'BULK_ANALYSIS_REQUEST_NOT_FOUND' using errcode = 'P0002';
  end if;

  select * into attempt_row
  from public.bulk_deck_analysis_attempts attempts
  where attempts.request_id = request_row.id
  for update;

  if request_row.status = 'processing' and request_row.expires_at <= recovery_time then
    if attempt_row.request_id is not null
       and attempt_row.attempt_status = 'claimed'
       and attempt_row.provider_attempt_count = 1 then
      update public.bulk_deck_analysis_attempts
      set attempt_status = 'unknown_outcome',
          provider_finished_at = recovery_time,
          provider_outcome_code = 'PROVIDER_OUTCOME_UNKNOWN'
      where request_id = request_row.id;
      update public.bulk_deck_analysis_requests
      set status = 'failed', failed_at = recovery_time,
          terminal_code = 'PROVIDER_OUTCOME_UNKNOWN'
      where id = request_row.id;
      return jsonb_build_object(
        'request_id', request_row.id, 'status', 'failed',
        'code', 'PROVIDER_OUTCOME_UNKNOWN'
      );
    end if;
    update public.bulk_deck_analysis_requests
    set status = 'expired', expired_at = recovery_time,
        terminal_code = 'RESERVATION_EXPIRED'
    where id = request_row.id;
    return jsonb_build_object(
      'request_id', request_row.id, 'status', 'expired',
      'code', 'RESERVATION_EXPIRED'
    );
  end if;

  if request_row.status = 'completed' then
    if attempt_row.request_id is null or attempt_row.attempt_status <> 'accepted' then
      raise exception 'BULK_ANALYSIS_COMPLETED_ARTIFACT_MISSING' using errcode = 'P0001';
    end if;
    if attempt_row.retained_until <= recovery_time then
      return jsonb_build_object(
        'request_id', request_row.id, 'status', 'completed',
        'code', 'COMPLETED_RESULT_EXPIRED',
        'result_schema_version', attempt_row.result_schema_version
      );
    end if;
    return jsonb_build_object(
      'request_id', request_row.id, 'status', 'completed',
      'code', 'COMPLETED',
      'accepted_result', attempt_row.accepted_result,
      'accepted_result_hash', attempt_row.accepted_result_hash,
      'result_schema_version', attempt_row.result_schema_version,
      'accepted_at', attempt_row.accepted_at,
      'retained_until', attempt_row.retained_until
    );
  end if;

  if request_row.status = 'failed' then
    return jsonb_build_object(
      'request_id', request_row.id, 'status', 'failed',
      'code', request_row.terminal_code
    );
  end if;
  if request_row.status = 'expired' then
    return jsonb_build_object(
      'request_id', request_row.id, 'status', 'expired',
      'code', request_row.terminal_code
    );
  end if;

  return jsonb_build_object(
    'request_id', request_row.id, 'status', 'processing',
    'code', case when attempt_row.request_id is null
      then 'AWAITING_CLAIM' else 'PROVIDER_IN_PROGRESS' end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_bulk_deck_analysis_request_status(p_request_id uuid DEFAULT NULL::uuid, p_idempotency_key uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  request_row public.bulk_deck_analysis_requests;
begin
  if current_user_id is null then
    raise exception 'BULK_ANALYSIS_AUTH_REQUIRED' using errcode = '28000';
  end if;
  if (p_request_id is null) = (p_idempotency_key is null) then
    raise exception 'BULK_ANALYSIS_STATUS_IDENTITY_INVALID' using errcode = '22023';
  end if;

  select * into request_row
  from public.bulk_deck_analysis_requests requests
  where requests.user_id = current_user_id
    and ((p_request_id is not null and requests.id = p_request_id)
      or (p_idempotency_key is not null
        and requests.idempotency_key = p_idempotency_key))
  for update;
  if request_row.id is null then
    raise exception 'BULK_ANALYSIS_REQUEST_NOT_FOUND' using errcode = 'P0002';
  end if;
  if request_row.status = 'processing'
     and request_row.expires_at <= clock_timestamp() then
    update public.bulk_deck_analysis_requests
    set status = 'expired', expired_at = clock_timestamp(),
        terminal_code = 'RESERVATION_EXPIRED'
    where id = request_row.id
    returning * into request_row;
  end if;
  return public.bulk_deck_analysis_request_json(request_row);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_bulk_deck_analysis_usage_snapshot()
 RETURNS jsonb
