$function$

CREATE OR REPLACE FUNCTION public.get_connected_match_monthly_limit(p_user_id uuid)
 RETURNS TABLE(monthly_limit integer, entitlement_source text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  has_sanctum_access boolean := false;
begin
  if p_user_id is null then
    monthly_limit := 10;
    entitlement_source := 'fallback_free';
    return next;
    return;
  end if;

  select exists (
    select 1
    from public.user_entitlements entitlements
    where entitlements.user_id = p_user_id
      and entitlements.entitlement_key in ('sanctum', 'store_owner')
      and (
        entitlements.status in ('active', 'trialing', 'grace_period')
        or (
          entitlements.status = 'cancelled'
          and entitlements.current_period_end is not null
          and entitlements.current_period_end > now()
        )
      )
  )
  into has_sanctum_access;

  if has_sanctum_access then
    monthly_limit := 30;
    entitlement_source := 'sanctum';
  else
    monthly_limit := 10;
    entitlement_source := 'free';
  end if;

  monthly_limit := least(monthly_limit, 30);
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_connected_match_monthly_usage()
 RETURNS TABLE(usage_month date, used_count integer, monthly_limit integer, remaining_count integer, entitlement_source text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  limit_record record;
begin
  if current_user_id is null then
    raise exception 'Authentication is required to view Connected Match usage.'
      using errcode = '28000';
  end if;

  usage_month := public.connected_match_usage_month_utc();

  select *
  into limit_record
  from public.get_connected_match_monthly_limit(current_user_id)
  limit 1;

  monthly_limit := limit_record.monthly_limit;
  entitlement_source := limit_record.entitlement_source;

  select coalesce(usage.connected_games_counted, 0)
  into used_count
  from public.connected_match_monthly_usage usage
  where usage.user_id = current_user_id
    and usage.usage_month = get_connected_match_monthly_usage.usage_month;

  used_count := coalesce(used_count, 0);
  remaining_count := greatest(monthly_limit - used_count, 0);

  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_entitlement_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  current_session_id uuid := public.sanctum_beta_jwt_session_id();
  sanctum_entitlement public.user_entitlements;
  store_owner_entitlement public.user_entitlements;
  sanctum_plan public.app_subscription_plans;
  store_owner_plan public.app_subscription_plans;
  active_beta_grant public.sanctum_beta_grants;
  has_direct_sanctum_access boolean := false;
  has_store_owner_access boolean := false;
  has_beta_sanctum_access boolean := false;
  has_sanctum_access boolean := false;
  resolved_tier text := 'free';
  resolved_status text := 'free';
  resolved_access_source text := 'free';
  resolved_period_end timestamptz := null;
  resolved_beta_expires_at timestamptz := null;
  resolved_monthly_token_grant integer := 0;
  resolved_capabilities jsonb := '{}'::jsonb;
  resolved_limits jsonb := '{}'::jsonb;
begin
  if current_user_id is not null then
    select *
    into sanctum_entitlement
    from public.user_entitlements
    where user_id = current_user_id
      and entitlement_key = 'sanctum'
    limit 1;

    select *
    into store_owner_entitlement
    from public.user_entitlements
    where user_id = current_user_id
      and entitlement_key = 'store_owner'
    limit 1;

    if current_session_id is not null then
      select grants.*
      into active_beta_grant
      from public.sanctum_beta_grants grants
      join public.sanctum_beta_programs programs
        on programs.id = grants.program_id
      join public.sanctum_beta_testers testers
        on testers.program_id = grants.program_id
       and testers.user_id = grants.user_id
       and testers.revoked_at is null
      where grants.user_id = current_user_id
        and grants.session_id = current_session_id
        and grants.revoked_at is null
        and grants.expires_at > now()
        and public.sanctum_beta_auth_session_is_active(
          current_user_id,
          current_session_id
        )
      order by grants.expires_at desc
      limit 1;
    end if;
  end if;

  select *
  into sanctum_plan
  from public.app_subscription_plans
  where plan_key = 'sanctum'
  limit 1;

  select *
  into store_owner_plan
  from public.app_subscription_plans
  where plan_key = 'store_owner'
  limit 1;

  if sanctum_entitlement.id is not null then
    has_direct_sanctum_access :=
      sanctum_entitlement.status in ('active', 'trialing', 'grace_period')
      or (
        sanctum_entitlement.status = 'cancelled'
        and sanctum_entitlement.current_period_end is not null
        and sanctum_entitlement.current_period_end > now()
      );
  end if;

  if store_owner_entitlement.id is not null then
    has_store_owner_access :=
      store_owner_entitlement.status in ('active', 'trialing', 'grace_period')
      or (
        store_owner_entitlement.status = 'cancelled'
        and store_owner_entitlement.current_period_end is not null
        and store_owner_entitlement.current_period_end > now()
      );
  end if;

  has_beta_sanctum_access := active_beta_grant.id is not null;
  has_sanctum_access :=
    has_store_owner_access
    or has_direct_sanctum_access
    or has_beta_sanctum_access;

  if has_store_owner_access then
    resolved_tier := 'store_owner';
    resolved_status := store_owner_entitlement.status;
    resolved_access_source := 'store_owner';
    resolved_period_end := store_owner_entitlement.current_period_end;
    resolved_monthly_token_grant := coalesce(
      nullif(store_owner_entitlement.monthly_token_grant, 0),
      nullif(store_owner_plan.monthly_token_grant, 0),
      nullif(sanctum_plan.monthly_token_grant, 0),
      0
    );
  elsif has_direct_sanctum_access then
    resolved_tier := 'sanctum';
    resolved_status := sanctum_entitlement.status;
    resolved_access_source := 'paid';
    resolved_period_end := sanctum_entitlement.current_period_end;
    resolved_monthly_token_grant := coalesce(
      nullif(sanctum_entitlement.monthly_token_grant, 0),
      sanctum_plan.monthly_token_grant,
      0
    );
  elsif has_beta_sanctum_access then
    resolved_tier := 'sanctum';
    resolved_status := 'beta';
    resolved_access_source := 'beta';
    resolved_period_end := active_beta_grant.expires_at;
    resolved_beta_expires_at := active_beta_grant.expires_at;
    resolved_monthly_token_grant := coalesce(
      nullif(sanctum_plan.monthly_token_grant, 0),
      100
    );
  end if;

  select coalesce(
    jsonb_object_agg(capability_key, enabled order by entitlement_key, capability_key),
    '{}'::jsonb
  )
  into resolved_capabilities
  from public.entitlement_capabilities
  where entitlement_key = 'free'
    or (has_sanctum_access and entitlement_key = 'sanctum')
    or (has_store_owner_access and entitlement_key = 'store_owner');

  select coalesce(
    jsonb_object_agg(capability_key, limit_value order by entitlement_key, capability_key),
    '{}'::jsonb
  )
  into resolved_limits
  from public.entitlement_capabilities
  where limit_value is not null
    and (
      entitlement_key = 'free'
      or (has_sanctum_access and entitlement_key = 'sanctum')
      or (has_store_owner_access and entitlement_key = 'store_owner')
    );

  return jsonb_build_object(
    'tier', resolved_tier,
    'has_sanctum', has_sanctum_access,
    'has_store_owner', has_store_owner_access,
    'monthly_token_grant', resolved_monthly_token_grant,
    'status', resolved_status,
    'access_source', resolved_access_source,
    'current_period_end', resolved_period_end,
    'beta_expires_at', resolved_beta_expires_at,
    'capabilities', resolved_capabilities,
    'limits', resolved_limits
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_store_checkin_reward_result(p_store_id uuid)
 RETURNS TABLE(ok boolean, status text, amount integer, store_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  today date := (now() at time zone 'utc')::date;
  active_store record;
  caller_is_checked_in boolean;
  today_award record;
  has_campaign boolean;
begin
  if current_user_id is null then
    raise exception 'Authentication is required to read store reward results.'
      using errcode = '28000';
  end if;

  select stores.id, stores.name
  into active_store
  from public.stores
  where stores.id = p_store_id
    and stores.is_public
    and stores.is_active;

  if active_store.id is null then
    raise exception 'This store check-in link is no longer active.'
      using errcode = 'P0002';
  end if;

  select exists (
    select 1
    from public.store_checkins
    where store_checkins.store_id = active_store.id
      and store_checkins.user_id = current_user_id
      and store_checkins.check_in_date = today
  )
  into caller_is_checked_in;

  if not caller_is_checked_in then
    raise exception 'Check in before reading store reward results.'
      using errcode = '42501';
  end if;

  perform public.reconcile_store_reward_campaigns(p_store_id);

  select *
  into today_award
  from public.store_reward_campaign_daily_awards
  where store_reward_campaign_daily_awards.store_id = p_store_id
    and store_reward_campaign_daily_awards.reward_date = today
  limit 1;

  if today_award.id is not null then
    if today_award.user_id = current_user_id then
      return query
      select true, 'won'::text, today_award.token_amount, active_store.name;
      return;
    end if;

    return query
    select true, 'not_selected'::text, null::integer, active_store.name;
    return;
  end if;

  select exists (
    select 1
    from public.store_reward_campaigns
    where store_reward_campaigns.store_id = p_store_id
      and store_reward_campaigns.active
      and store_reward_campaigns.start_date <= today
      and store_reward_campaigns.end_date >= today
  )
  into has_campaign;

  if has_campaign then
    return query
    select true, 'pending'::text, null::integer, active_store.name;
    return;
  end if;

  return query
  select true, 'no_campaign'::text, null::integer, active_store.name;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_sanctum_beta_redemption_throttle_admin(p_program_key text, p_user_id uuid, p_ip_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  beta_program_id uuid;
  user_recent_attempts integer := 0;
  ip_recent_attempts integer := 0;
begin
  if p_user_id is null then
    return jsonb_build_object('allowed', false);
  end if;

  select id
  into beta_program_id
  from public.sanctum_beta_programs
  where program_key = p_program_key
  limit 1;

  select count(*)
  into user_recent_attempts
  from public.sanctum_beta_redemption_attempts attempts
  where attempts.user_id = p_user_id
    and (beta_program_id is null or attempts.program_id = beta_program_id)
    and attempts.attempted_at > now() - interval '15 minutes'
    and attempts.succeeded = false;

  if nullif(p_ip_fingerprint, '') is not null then
    select count(*)
    into ip_recent_attempts
    from public.sanctum_beta_redemption_attempts attempts
    where attempts.ip_fingerprint = p_ip_fingerprint
      and (beta_program_id is null or attempts.program_id = beta_program_id)
      and attempts.attempted_at > now() - interval '15 minutes'
      and attempts.succeeded = false;
  end if;

  return jsonb_build_object(
    'allowed', user_recent_attempts < 5 and ip_recent_attempts < 25
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_sanctum_beta_monthly_tokens_admin(p_user_id uuid, p_program_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  grant_month date := date_trunc('month', now())::date;
  token_amount integer := 100;
  inserted_grant_id uuid;
begin
  if p_user_id is null then
    raise exception 'User is required.' using errcode = '23502';
  end if;

  if public.sanctum_beta_user_has_active_entitlement(p_user_id, 'store_owner')
    or public.sanctum_beta_user_has_active_entitlement(p_user_id, 'sanctum') then
    return false;
  end if;

  insert into public.user_token_grants (
    user_id,
    source,
    grant_month,
    amount,
    program_id,
    metadata
  )
  values (
    p_user_id,
    'sanctum_beta',
    grant_month,
    token_amount,
    p_program_id,
    jsonb_build_object('grant_month', to_char(grant_month, 'YYYY-MM'))
  )
  on conflict (user_id, source, grant_month) do nothing
  returning id into inserted_grant_id;

  if inserted_grant_id is null then
    return false;
  end if;

  insert into public.user_token_wallets (user_id)
  values (p_user_id)
  on conflict (user_id) do nothing;

  update public.user_token_wallets
  set
    token_balance = token_balance + token_amount,
    lifetime_granted = lifetime_granted + token_amount
  where user_id = p_user_id;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_user_tokens(target_user_id uuid, amount integer)
 RETURNS user_token_wallets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  wallet public.user_token_wallets;
begin
  if public.current_user_role() not in ('Admin', 'SuperAdmin') then
    raise exception 'Only Admin or SuperAdmin can grant tokens.'
      using errcode = '42501';
  end if;

  if target_user_id is null then
    raise exception 'Target user is required.'
      using errcode = '23502';
  end if;

  if amount is null or amount <= 0 then
    raise exception 'Grant amount must be greater than zero.'
      using errcode = '22023';
  end if;

  perform public.ensure_user_token_wallet(target_user_id);

  update public.user_token_wallets
  set
    token_balance = token_balance + amount,
    lifetime_granted = lifetime_granted + amount
  where user_id = target_user_id
  returning * into wallet;

  return wallet;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_store_welcome_message_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.store_welcome_message is distinct from old.store_welcome_message
    or new.store_welcome_message_enabled is distinct from old.store_welcome_message_enabled
    or new.store_welcome_message_updated_at is distinct from old.store_welcome_message_updated_at
  then
    if not new.is_active then
      raise exception 'Store Welcome Message can only be updated for an active store.'
        using errcode = 'P0002';
    end if;

    if not public.is_store_staff(new.id) then
      raise exception 'You are not authorized to update this store welcome message.'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_auth_user_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  requested_username text;
  normalized_username text;
begin
  requested_username := nullif(btrim(new.raw_user_meta_data ->> 'username'), '');

  if requested_username is null then
    raise exception 'Username is required.'
      using errcode = '23514';
  end if;

  if not public.is_valid_username(requested_username) then
    raise exception 'Username must be 3-24 characters and use only letters, numbers, or underscores.'
      using errcode = '23514';
  end if;

  normalized_username := public.normalize_username(requested_username);

  insert into public.username_reservations (
    username_normalized,
    username_display,
    claimed_by
  )
  values (
    normalized_username,
    btrim(requested_username),
    new.id
  );

  insert into public.profiles (
    user_id,
    username_normalized,
    username_display,
    role
  )
  values (
    new.id,
    normalized_username,
    btrim(requested_username),
    'Player'
  );

  return new;
exception
  when unique_violation then
    raise exception 'Username is already reserved.'
      using errcode = '23505';
end;
$function$

CREATE OR REPLACE FUNCTION public.heartbeat_connected_match(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  participant_record public.connected_match_participants;
begin
  if current_user_id is null then
    raise exception 'Authentication is required to heartbeat a Connected Match.'
      using errcode = '28000';
  end if;

  update public.connected_match_participants participants
  set
    last_seen_at = now(),
    reconnect_until = now() + interval '30 minutes'
  where participants.session_id = p_session_id
    and participants.user_id = current_user_id
  returning *
  into participant_record;

  if participant_record.id is null then
    raise exception 'You are not part of this Connected Match.'
      using errcode = '42501';
  end if;

  return row_to_json(participant_record)::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION public.join_connected_match(p_join_code text, p_player jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(session jsonb, participant jsonb, monthly_usage jsonb, reconnected boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  normalized_join_code text := upper(btrim(coalesce(p_join_code, '')));
  player_payload record;
  usage_payload record;
  session_record public.connected_match_sessions;
  participant_record public.connected_match_participants;
  next_seat integer;
begin
  if current_user_id is null then
    raise exception 'Authentication is required to join a Connected Match.'
      using errcode = '28000';
  end if;

  select *
  into session_record
  from public.connected_match_sessions sessions
  where sessions.join_code = normalized_join_code
  for update;

  if session_record.id is null then
    raise exception 'Connected Match not found.'
      using errcode = 'P0002';
  end if;

  if session_record.expires_at <= now() then
    raise exception 'This Connected Match invite has expired.'
      using errcode = '22023';
  end if;

  select *
  into player_payload
  from public.connected_match_build_player_payload(coalesce(p_player, '{}'::jsonb), current_user_id)
  limit 1;

  select *
  into participant_record
  from public.connected_match_participants participants
  where participants.session_id = session_record.id
    and participants.user_id = current_user_id
  for update;

  if participant_record.id is not null then
    if session_record.status not in ('lobby', 'active') then
      raise exception 'This Connected Match is no longer available for reconnect.'
        using errcode = '22023';
    end if;

    update public.connected_match_participants
    set
      display_name = player_payload.display_name,
      avatar_ref = player_payload.avatar_ref,
      commander_name = player_payload.commander_name,
      commander_scryfall_id = player_payload.commander_scryfall_id,
      commander_image_url = player_payload.commander_image_url,
      commander_art_crop_url = player_payload.commander_art_crop_url,
      terminal_state = 'active',
      elimination_reason = null,
      left_mid_game = false,
      is_ready = true,
      ready_at = coalesce(ready_at, now()),
      last_seen_at = now(),
      reconnect_until = now() + interval '30 minutes'
    where id = participant_record.id
    returning *
    into participant_record;

    select *
    into usage_payload
    from public.get_connected_match_monthly_usage()
    limit 1;

    session := row_to_json(session_record)::jsonb;
    participant := row_to_json(participant_record)::jsonb;
    monthly_usage := jsonb_build_object(
      'usage_month', usage_payload.usage_month,
      'used_count', usage_payload.used_count,
      'monthly_limit', usage_payload.monthly_limit,
      'remaining_count', usage_payload.remaining_count,
      'entitlement_source', usage_payload.entitlement_source
    );
    reconnected := true;
    return next;
    return;
  end if;

  if session_record.status <> 'lobby' then
    raise exception 'This Connected Match is no longer accepting new players.'
      using errcode = '22023';
  end if;

  if (
    select count(*)
    from public.connected_match_participants participants
    where participants.session_id = session_record.id
      and participants.terminal_state = 'active'
  ) >= session_record.max_players then
    raise exception 'This Connected Match is full.'
      using errcode = '22023';
  end if;

  select *
  into usage_payload
  from public.reserve_connected_match_usage(current_user_id, 'joined')
  limit 1;

  select seat
  into next_seat
  from generate_series(0, session_record.max_players - 1) as seat
  where not exists (
    select 1
    from public.connected_match_participants participants
    where participants.session_id = session_record.id
      and participants.seat_index = seat
      and participants.terminal_state = 'active'
  )
  order by seat
  limit 1;

  insert into public.connected_match_participants (
    session_id,
    user_id,
    seat_index,
    display_name,
    avatar_ref,
    commander_name,
    commander_scryfall_id,
    commander_image_url,
    commander_art_crop_url,
    life,
    is_ready,
    ready_at,
    reconnect_until
  )
  values (
    session_record.id,
    current_user_id,
    next_seat,
    player_payload.display_name,
    player_payload.avatar_ref,
    player_payload.commander_name,
    player_payload.commander_scryfall_id,
    player_payload.commander_image_url,
    player_payload.commander_art_crop_url,
    session_record.starting_life,
    true,
    now(),
    now() + interval '30 minutes'
  )
  returning *
  into participant_record;

  insert into public.connected_match_events (
    session_id,
    participant_id,
    event_type,
    payload
  )
  values (
    session_record.id,
    participant_record.id,
    'participant_joined',
    jsonb_build_object('user_id', current_user_id, 'seat_index', next_seat)
  );

  session := row_to_json(session_record)::jsonb;
  participant := row_to_json(participant_record)::jsonb;
  monthly_usage := jsonb_build_object(
    'usage_month', usage_payload.usage_month,
    'used_count', usage_payload.used_count,
    'monthly_limit', usage_payload.monthly_limit,
    'remaining_count', usage_payload.remaining_count,
    'entitlement_source', usage_payload.entitlement_source
  );
  reconnected := false;

  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_account_deletion(p_request_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  job_row public.account_deletion_jobs;
  profile_row public.profiles;
  auth_email text;
  label_values text[];
  null_values text[];
  target_participant_ids uuid[];
  existing_request_user uuid;
  existing_request_fingerprint text;
  existing_user_request uuid;
begin
  if p_request_id is null or p_user_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_REQUEST',
      'retryable', false
    );
  end if;

  -- Transaction-scoped per-user serialization prevents concurrent jobs from
  -- interleaving even before the job row exists.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_user_id::text, 90210)
  );

  select jobs.user_id, jobs.user_fingerprint
  into existing_request_user, existing_request_fingerprint
  from public.account_deletion_jobs as jobs
  where jobs.request_id = p_request_id;

  if found
     and existing_request_user is distinct from p_user_id
     and existing_request_fingerprint <> encode(
       extensions.digest(p_user_id::text, 'sha256'),
       'hex'
     ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'IDEMPOTENCY_TARGET_MISMATCH',
      'retryable', false
    );
  end if;

  select jobs.request_id
  into existing_user_request
  from public.account_deletion_jobs as jobs
  where jobs.user_id = p_user_id;

  if found and existing_user_request is distinct from p_request_id then
    return jsonb_build_object(
      'ok', false,
      'code', 'DELETION_ALREADY_REQUESTED',
      'retryable', false
    );
  end if;

  insert into public.account_deletion_jobs (
    request_id,
    user_id,
    user_fingerprint
  )
  values (
    p_request_id,
    p_user_id,
    encode(extensions.digest(p_user_id::text, 'sha256'), 'hex')
  )
  on conflict (request_id) do nothing;

  select jobs.*
  into job_row
  from public.account_deletion_jobs as jobs
  where jobs.request_id = p_request_id
  for update;

  if job_row.database_cleaned_at is not null then
    return jsonb_build_object(
      'ok', true,
      'code', 'DATABASE_ALREADY_CLEANED',
      'request_id', job_row.request_id,
      'status', job_row.status,
      'retryable', false
    );
  end if;

  -- Product blocker: this check precedes every destructive statement.
  if exists (
    select 1
    from public.stores
    where owner_id = p_user_id
  ) then
    update public.account_deletion_jobs
    set attempt_count = attempt_count + 1,
        last_error_code = 'STORE_OWNERSHIP_ACTION_REQUIRED',
        updated_at = now()
    where id = job_row.id;

    return jsonb_build_object(
      'ok', false,
      'code', 'STORE_OWNERSHIP_ACTION_REQUIRED',
      'request_id', p_request_id,
      'status', 'requested',
      'retryable', false
    );
  end if;

  select profiles.*
  into profile_row
  from public.profiles as profiles
  where profiles.user_id = p_user_id;

  select users.email
  into auth_email
  from auth.users as users
  where users.id = p_user_id;

  label_values := array_remove(array[
    profile_row.username_normalized,
    profile_row.username_display,
    profile_row.display_name
  ], null);
  null_values := array_remove(array[
    p_user_id::text,
    auth_email,
    profile_row.avatar_url
  ], null);

  update public.account_deletion_jobs
  set attempt_count = attempt_count + 1,
      last_error_code = null,
      updated_at = now()
  where id = job_row.id;

  -- 1. Preserve and anonymize shared connected-play records.
  select coalesce(array_agg(participants.id), array[]::uuid[])
  into target_participant_ids
  from public.connected_match_participants as participants
  where participants.user_id = p_user_id;

  update public.connected_match_sessions as sessions
  set host_user_id = (
        select participants.user_id
        from public.connected_match_participants as participants
        where participants.session_id = sessions.id
          and participants.user_id is not null
          and participants.user_id <> p_user_id
        order by participants.seat_index, participants.id
        limit 1
      )
  where sessions.host_user_id = p_user_id;

  update public.connected_game_history
  set participant_user_ids = array_remove(participant_user_ids, p_user_id),
      winner_user_id = case
        when winner_user_id = p_user_id then null
        else winner_user_id
      end,
      participants = public.scrub_account_identity_json(
        participants, label_values, null_values
      ),
      commanders = public.scrub_account_identity_json(
        commanders, label_values, null_values
      ),
      final_result = public.scrub_account_identity_json(
        final_result, label_values, null_values
      ),
      left_mid_game = public.scrub_account_identity_json(
        left_mid_game, label_values, null_values
      )
  where p_user_id = any(participant_user_ids)
     or winner_user_id = p_user_id
     or participants::text like ('%' || p_user_id::text || '%')
     or commanders::text like ('%' || p_user_id::text || '%')
     or final_result::text like ('%' || p_user_id::text || '%')
     or left_mid_game::text like ('%' || p_user_id::text || '%');

  update public.connected_match_events
  set payload = public.scrub_account_identity_json(
    payload, label_values, null_values
  )
  where participant_id = any(target_participant_ids)
     or payload::text like ('%' || p_user_id::text || '%');

  update public.connected_match_participants
  set user_id = null,
      display_name = 'Deleted Player',
      avatar_ref = 'deck_sage_default'
  where user_id = p_user_id;

  -- 2. Anonymize operational and shared audit records.
  update public.notification_events
  set actor_user_id = null,
      payload = public.scrub_account_identity_json(
        payload, label_values, null_values
      )
  where actor_user_id = p_user_id;

  update public.entitlement_events
  set user_id = case when user_id = p_user_id then null else user_id end,
      created_by = case when created_by = p_user_id then null else created_by end,
      provider_customer_id = case
        when provider_customer_id = p_user_id::text
          or provider_customer_id = any(null_values)
        then null
        else provider_customer_id
      end,
      raw_event = public.scrub_account_identity_json(
        raw_event, label_values, null_values
      )
  where user_id = p_user_id
     or created_by = p_user_id
     or provider_customer_id = p_user_id::text
     or raw_event::text like ('%' || p_user_id::text || '%');

  update public.store_analytics_events
  set user_id = null,
      properties = public.scrub_account_identity_json(
        properties, label_values, null_values
      )
  where user_id = p_user_id;

  update public.store_rewards
  set user_id = case when user_id = p_user_id then null else user_id end,
      awarded_by = case when awarded_by = p_user_id then null else awarded_by end,
      metadata = public.scrub_account_identity_json(
        metadata, label_values, null_values
      )
  where user_id = p_user_id or awarded_by = p_user_id;

  update public.store_reward_campaign_daily_awards
  set user_id = null,
      checkin_id = case
        when checkin_id in (
          select checkins.id
          from public.store_checkins as checkins
          where checkins.user_id = p_user_id
        ) then null
        else checkin_id
      end
  where user_id = p_user_id;

  update public.store_reward_campaign_daily_awards
  set checkin_id = null
  where checkin_id in (
    select checkins.id
    from public.store_checkins as checkins
    where checkins.user_id = p_user_id
  );

  update public.store_staff set invited_by = null where invited_by = p_user_id;
  update public.store_reward_settings set updated_by = null where updated_by = p_user_id;
  update public.store_messages set created_by = null where created_by = p_user_id;
  update public.store_home_takeovers set created_by = null where created_by = p_user_id;
  update public.store_reward_campaigns set created_by = null where created_by = p_user_id;
  update public.store_subscription_plans set updated_by = null where updated_by = p_user_id;
  update public.app_subscription_plans set updated_by = null where updated_by = p_user_id;
  update public.premium_features set updated_by = null where updated_by = p_user_id;
  update public.sanctum_beta_testers
  set approved_by = case when approved_by = p_user_id then null else approved_by end,
      revoked_by = case when revoked_by = p_user_id then null else revoked_by end
  where approved_by = p_user_id or revoked_by = p_user_id;

  -- 3. Delete direct account-scoped data in dependency order.
  delete from public.bulk_deck_analysis_saved_reports where user_id = p_user_id;
  delete from public.bulk_deck_analysis_requests where user_id = p_user_id;
  delete from public.bulk_deck_analysis_monthly_usage where user_id = p_user_id;

  delete from public.notification_push_attempts where user_id = p_user_id;
  delete from public.notification_digest_items where user_id = p_user_id;
  delete from public.notification_digest_deliveries where user_id = p_user_id;
  delete from public.notification_events where recipient_user_id = p_user_id;
  delete from public.notification_preferences where user_id = p_user_id;
  delete from public.user_push_tokens where user_id = p_user_id;

  delete from public.store_lfg_interest
  where requesting_user_id = p_user_id
     or responding_user_id = p_user_id
     or pair_low_user_id = p_user_id
     or pair_high_user_id = p_user_id;
  delete from public.store_members where user_id = p_user_id;
  delete from public.store_staff where user_id = p_user_id;
  delete from public.store_checkins where user_id = p_user_id;
  delete from public.player_store_preferences where user_id = p_user_id;

  delete from public.sanctum_beta_grants where user_id = p_user_id;
  delete from public.sanctum_beta_redemption_attempts where user_id = p_user_id;
  delete from public.sanctum_beta_testers where user_id = p_user_id;
  delete from public.user_token_grants where user_id = p_user_id;
  delete from public.user_entitlements where user_id = p_user_id;
  delete from public.user_token_wallets where user_id = p_user_id;
  delete from public.connected_match_monthly_usage where user_id = p_user_id;

  delete from public.cloud_deck_commanders where owner_id = p_user_id;
  delete from public.cloud_deck_card_stacks where owner_id = p_user_id;
  delete from public.cloud_decks where owner_id = p_user_id;
  delete from public.cloud_bulk_card_stacks where owner_id = p_user_id;
  delete from public.cloud_sync_devices where owner_id = p_user_id;

  delete from public.friend_requests
  where requester_id = p_user_id or recipient_id = p_user_id;
  delete from public.username_reservations where claimed_by = p_user_id;
  delete from public.profiles where user_id = p_user_id;

  update public.account_deletion_jobs
  set status = 'db_cleaned',
      database_cleaned_at = now(),
      last_error_code = null,
      updated_at = now()
  where id = job_row.id;

  return jsonb_build_object(
    'ok', true,
    'code', 'DATABASE_CLEANED',
    'request_id', p_request_id,
    'status', 'db_cleaned',
    'retryable', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_friend_request_party_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.requester_id <> old.requester_id or new.recipient_id <> old.recipient_id then
    raise exception 'Friend request users cannot be changed.';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.push_cloud_bulk_card_stacks(stacks jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  acting_owner_id uuid := auth.uid();
  sync_revision timestamptz := transaction_timestamp();
  stack_count integer;
  stack_record jsonb;
  processed_count integer := 0;
  updated_row record;
  updated_rows jsonb := '[]'::jsonb;
begin
  if acting_owner_id is null then
    raise exception 'Authentication is required.'
      using errcode = '28000';
  end if;

  if jsonb_typeof(coalesce(stacks, 'null'::jsonb)) <> 'array' then
    raise exception 'stacks must be a JSON array.'
      using errcode = '23514';
  end if;

  stack_count := jsonb_array_length(stacks);

  if stack_count > 250 then
    raise exception 'Bulk stack batch size cannot exceed 250 rows.'
      using errcode = '54000';
  end if;

  for stack_record in
    select value from jsonb_array_elements(stacks)
  loop
    if nullif(btrim(stack_record ->> 'local_id'), '') is null then
      raise exception 'Bulk stack local_id is required.'
        using errcode = '23514';
    end if;

    insert into public.cloud_bulk_card_stacks (
      owner_id,
      local_id,
      card_name,
      normalized_name,
      oracle_id,
      scryfall_id,
      variant,
      quantity,
      sync_status,
      client_updated_at,
      last_synced_at,
      deleted_at
    )
    values (
      acting_owner_id,
      stack_record ->> 'local_id',
      coalesce(nullif(stack_record ->> 'card_name', ''), 'Unknown Card'),
      coalesce(nullif(stack_record ->> 'normalized_name', ''), lower(coalesce(stack_record ->> 'card_name', ''))),
      nullif(stack_record ->> 'oracle_id', ''),
      nullif(stack_record ->> 'scryfall_id', ''),
      coalesce(nullif(stack_record ->> 'variant', ''), 'Normal'),
      greatest(0, coalesce(nullif(stack_record ->> 'quantity', '')::integer, 0)),
      coalesce(nullif(stack_record ->> 'sync_status', ''), 'synced'),
      coalesce(nullif(stack_record ->> 'client_updated_at', '')::timestamptz, sync_revision),
      nullif(stack_record ->> 'last_synced_at', '')::timestamptz,
      nullif(stack_record ->> 'deleted_at', '')::timestamptz
    )
    on conflict (owner_id, local_id)
    do update set
      card_name = excluded.card_name,
      normalized_name = excluded.normalized_name,
      oracle_id = excluded.oracle_id,
      scryfall_id = excluded.scryfall_id,
      variant = excluded.variant,
      quantity = excluded.quantity,
      sync_status = excluded.sync_status,
      client_updated_at = excluded.client_updated_at,
      last_synced_at = excluded.last_synced_at,
      deleted_at = excluded.deleted_at
    returning id, local_id, server_updated_at
    into updated_row;

    processed_count := processed_count + 1;
    updated_rows := updated_rows || jsonb_build_array(
      jsonb_build_object(
        'id', updated_row.id,
        'local_id', updated_row.local_id,
        'server_updated_at', updated_row.server_updated_at
      )
    );
  end loop;

  return jsonb_build_object(
    'sync_revision', sync_revision,
    'processed_count', processed_count,
    'rows', updated_rows
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.redeem_sanctum_beta_grant_admin(p_program_key text, p_user_id uuid, p_session_id uuid, p_ip_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  beta_program public.sanctum_beta_programs;
  beta_tester public.sanctum_beta_testers;
  beta_grant public.sanctum_beta_grants;
  now_at timestamptz := now();
  next_expires_at timestamptz := now_at + interval '24 hours';
  was_already_active boolean := false;
  token_granted boolean := false;
begin
  if p_user_id is null or p_session_id is null then
    raise exception 'Redemption failed.' using errcode = '42501';
  end if;

  if not public.sanctum_beta_auth_session_is_active(p_user_id, p_session_id) then
    raise exception 'Redemption failed.' using errcode = '42501';
  end if;

  select *
  into beta_program
  from public.sanctum_beta_programs
  where program_key = p_program_key
  limit 1;

  if beta_program.id is null then
    raise exception 'Redemption failed.' using errcode = '42501';
  end if;

  select *
  into beta_tester
  from public.sanctum_beta_testers
  where program_id = beta_program.id
    and user_id = p_user_id
    and revoked_at is null
  limit 1;

  if beta_tester.id is null then
    raise exception 'Redemption failed.' using errcode = '42501';
  end if;

  select *
  into beta_grant
  from public.sanctum_beta_grants
  where user_id = p_user_id
    and program_id = beta_program.id
    and session_id = p_session_id
  for update;

  if beta_grant.id is not null
    and beta_grant.revoked_at is null
    and beta_grant.expires_at > now_at then
    was_already_active := true;
  else
    if beta_program.redemptions_enabled is not true then
      raise exception 'Redemption failed.' using errcode = '42501';
    end if;

    insert into public.sanctum_beta_grants (
      program_id,
      user_id,
      session_id,
      granted_at,
      expires_at,
      revoked_at,
      revoked_reason
    )
    values (
      beta_program.id,
      p_user_id,
      p_session_id,
      now_at,
      next_expires_at,
      null,
      null
    )
    on conflict (user_id, program_id, session_id) do update set
      granted_at = excluded.granted_at,
      expires_at = excluded.expires_at,
      revoked_at = null,
      revoked_reason = null
    returning * into beta_grant;
  end if;

  token_granted :=
    public.grant_sanctum_beta_monthly_tokens_admin(p_user_id, beta_program.id);

  perform public.record_sanctum_beta_redemption_attempt_admin(
    p_program_key,
    p_user_id,
    p_ip_fingerprint,
    true
  );

  return jsonb_build_object(
    'expires_at', beta_grant.expires_at,
    'already_active', was_already_active,
    'token_granted', token_granted
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.request_store_staff_onboarding(store_name text)
 RETURNS store_staff
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  trimmed_name text := nullif(btrim(store_name), '');
  matched_store public.stores;
  staff_request public.store_staff;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.'
      using errcode = '28000';
  end if;

  if trimmed_name is null or length(trimmed_name) < 2 then
    raise exception 'Store name is required.'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.profiles
    where user_id = auth.uid()
      and store_onboarding_completed
  ) then
    raise exception 'Store onboarding has already been completed.'
      using errcode = '23505';
  end if;

  select *
  into matched_store
  from public.stores
  where lower(name) = lower(trimmed_name)
  order by created_at asc
  limit 1;

  if matched_store.id is null then
    raise exception 'Store not found. Ask the store owner to create the store first.'
      using errcode = 'P0002';
  end if;

  insert into public.store_staff (
    store_id,
    user_id,
    role,
    is_active,
    invited_by
  )
  values (
    matched_store.id,
    auth.uid(),
    'staff',
    public.current_user_role() in ('Admin', 'SuperAdmin'),
    auth.uid()
  )
  on conflict (store_id, user_id)
  do update set
    role = case
      when public.store_staff.is_active then public.store_staff.role
      else 'staff'
    end,
    is_active = public.store_staff.is_active
      or public.current_user_role() in ('Admin', 'SuperAdmin'),
    invited_by = auth.uid()
  returning * into staff_request;

  update public.profiles
  set
    store_onboarding_completed = true,
    store_onboarding_choice = 'store_staff',
    store_onboarding_completed_at = now()
  where user_id = auth.uid();

  return staff_request;
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_connected_match_usage(p_user_id uuid, p_kind text)
 RETURNS TABLE(usage_month date, used_count integer, monthly_limit integer, remaining_count integer, entitlement_source text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_month date := public.connected_match_usage_month_utc();
  usage_record public.connected_match_monthly_usage;
  limit_record record;
begin
  if p_user_id is null then
    raise exception 'Authentication is required to reserve Connected Match usage.'
      using errcode = '28000';
  end if;

  if p_kind not in ('started', 'joined') then
    raise exception 'Unknown Connected Match usage kind.'
      using errcode = '22023';
  end if;

  select *
  into limit_record
  from public.get_connected_match_monthly_limit(p_user_id)
  limit 1;

  insert into public.connected_match_monthly_usage (
    user_id,
    usage_month
  )
  values (
    p_user_id,
    current_month
  )
  on conflict on constraint connected_match_monthly_usage_user_month_unique
  do nothing;

  select *
  into usage_record
  from public.connected_match_monthly_usage usage
  where usage.user_id = p_user_id
    and usage.usage_month = current_month
  for update;

  if usage_record.connected_games_counted >= limit_record.monthly_limit then
    raise exception 'CONNECTED_MATCH_LIMIT_REACHED: You have used your Connected Matches for this month. Local tabletop gameplay is still free and unlimited.'
      using errcode = 'P0001';
  end if;

  update public.connected_match_monthly_usage usage
  set
    connected_games_started =
      usage.connected_games_started + case when p_kind = 'started' then 1 else 0 end,
    connected_games_joined =
      usage.connected_games_joined + case when p_kind = 'joined' then 1 else 0 end,
    connected_games_counted = usage.connected_games_counted + 1
  where usage.user_id = p_user_id
    and usage.usage_month = current_month
  returning *
  into usage_record;

  usage_month := current_month;
  used_count := usage_record.connected_games_counted;
  monthly_limit := limit_record.monthly_limit;
  remaining_count := greatest(limit_record.monthly_limit - usage_record.connected_games_counted, 0);
  entitlement_source := limit_record.entitlement_source;

  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_my_sanctum_beta_grant()
