CREATE OR REPLACE FUNCTION public.scrub_account_identity_json(p_value jsonb, p_deleted_label_values text[], p_deleted_null_values text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  result_value jsonb;
begin
  if p_value is null then
    return null;
  end if;

  case jsonb_typeof(p_value)
    when 'object' then
      select coalesce(
        jsonb_object_agg(item.key, public.scrub_account_identity_json(
          item.value,
          p_deleted_label_values,
          p_deleted_null_values
        )),
        '{}'::jsonb
      )
      into result_value
      from jsonb_each(p_value) as item;
      return result_value;
    when 'array' then
      select coalesce(
        jsonb_agg(public.scrub_account_identity_json(
          item.value,
          p_deleted_label_values,
          p_deleted_null_values
        ) order by item.ordinality),
        '[]'::jsonb
      )
      into result_value
      from jsonb_array_elements(p_value) with ordinality as item(value, ordinality);
      return result_value;
    when 'string' then
      if p_value #>> '{}' = any(coalesce(p_deleted_label_values, array[]::text[])) then
        return to_jsonb('Deleted Player'::text);
      end if;
      if p_value #>> '{}' = any(coalesce(p_deleted_null_values, array[]::text[])) then
        return 'null'::jsonb;
      end if;
      return p_value;
    else
      return p_value;
  end case;
end;
$function$

