CREATE OR REPLACE FUNCTION public.set_connected_terminal_state(p_session_id uuid, p_state text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  normalized_state text := btrim(coalesce(p_state, ''));
  normalized_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  participant_record public.connected_match_participants;
begin
  if current_user_id is null then
    raise exception 'Authentication is required to update Connected Match state.'
      using errcode = '28000';
  end if;

  if normalized_state not in ('won', 'lost', 'left') then
    raise exception 'Unknown Connected Match terminal state.'
      using errcode = '22023';
  end if;

  if normalized_reason is not null
    and normalized_reason not in ('life_total', 'poison', 'commander_damage', 'manual', 'left', 'unknown') then
    raise exception 'Unknown Connected Match elimination reason.'
      using errcode = '22023';
  end if;

  update public.connected_match_participants participants
  set
    terminal_state = normalized_state,
    elimination_reason =
      case
        when normalized_state = 'won' then null
        when normalized_state = 'left' then 'left'
        else coalesce(normalized_reason, 'manual')
      end,
    left_mid_game = case when normalized_state = 'left' then true else participants.left_mid_game end,
    last_seen_at = now(),
    reconnect_until = now() + interval '30 minutes'
  where participants.session_id = p_session_id
    and participants.user_id = current_user_id
  returning *
  into participant_record;

  if participant_record.id is null then
    raise exception 'You are not part of this Connected Match.'
      using errcode = '42501';
  end if;

  perform public.connected_match_complete_if_ready(p_session_id);

  return row_to_json(participant_record)::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_sanctum_avatar(p_avatar_id text, p_complete_onboarding boolean DEFAULT false)
 RETURNS profiles
 LANGUAGE plpgsql
