 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  normalized_avatar_id text := nullif(btrim(coalesce(p_avatar_id, '')), '');
  updated_profile public.profiles;
begin
  if current_user_id is null then
    raise exception 'Authentication is required to update your Sanctum avatar.'
      using errcode = '28000';
  end if;

  if normalized_avatar_id is null
    or not public.is_valid_sanctum_avatar_id(normalized_avatar_id) then
    raise exception 'Invalid Sanctum avatar.'
      using errcode = '23514';
  end if;

  update public.profiles
  set
    sanctum_avatar_id = normalized_avatar_id,
    sanctum_avatar_onboarded_at = case
      when p_complete_onboarding then coalesce(sanctum_avatar_onboarded_at, now())
      else sanctum_avatar_onboarded_at
    end
  where user_id = current_user_id
  returning *
  into updated_profile;

  if updated_profile.user_id is null then
    raise exception 'Profile not found.'
      using errcode = 'P0002';
  end if;

  return updated_profile;
end;
$function$

