CREATE OR REPLACE FUNCTION public.spend_user_tokens(target_user_id uuid, amount integer)
 RETURNS user_token_wallets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  wallet public.user_token_wallets;
begin
  if target_user_id is null then
    raise exception 'Target user is required.'
      using errcode = '23502';
  end if;

  if target_user_id <> auth.uid()
    and public.current_user_role() not in ('Admin', 'SuperAdmin') then
    raise exception 'Users can only spend their own tokens.'
      using errcode = '42501';
  end if;

  if amount is null or amount <= 0 then
    raise exception 'Spend amount must be greater than zero.'
      using errcode = '22023';
  end if;

  perform public.ensure_user_token_wallet(target_user_id);

  update public.user_token_wallets
  set
    token_balance = token_balance - amount,
    lifetime_spent = lifetime_spent + amount
  where user_id = target_user_id
    and token_balance >= amount
  returning * into wallet;

  if wallet.user_id is null then
    raise exception 'Insufficient token balance.'
      using errcode = '22023';
  end if;

  return wallet;
end;
$function$

CREATE OR REPLACE FUNCTION public.start_bulk_deck_analysis_request(p_idempotency_key uuid, p_request_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  current_session_id uuid := public.sanctum_beta_jwt_session_id();
  current_month date := public.bulk_deck_analysis_month_utc();
  entitlement record;
  aggregate_row public.bulk_deck_analysis_monthly_usage;
  request_row public.bulk_deck_analysis_requests;
  active_count integer := 0;
begin
  if current_user_id is null then
    raise exception 'BULK_ANALYSIS_AUTH_REQUIRED' using errcode = '28000';
  end if;
  if p_idempotency_key is null then
    raise exception 'BULK_ANALYSIS_IDEMPOTENCY_KEY_REQUIRED' using errcode = '22023';
  end if;
  p_request_fingerprint := btrim(coalesce(p_request_fingerprint, ''));
  if length(p_request_fingerprint) not between 16 and 256
     or p_request_fingerprint !~ '^[A-Za-z0-9._:-]+$' then
    raise exception 'BULK_ANALYSIS_FINGERPRINT_INVALID' using errcode = '22023';
  end if;

  select * into request_row
  from public.bulk_deck_analysis_requests requests
  where requests.user_id = current_user_id
    and requests.idempotency_key = p_idempotency_key
  for update;

  if request_row.id is not null then
    if request_row.request_fingerprint <> p_request_fingerprint then
      raise exception 'BULK_ANALYSIS_IDEMPOTENCY_CONFLICT' using errcode = 'P0001';
    end if;
    if request_row.status = 'processing'
       and request_row.expires_at <= clock_timestamp() then
      update public.bulk_deck_analysis_requests
      set status = 'expired', expired_at = clock_timestamp(),
          terminal_code = 'RESERVATION_EXPIRED'
      where id = request_row.id
      returning * into request_row;
    end if;
    return jsonb_build_object(
      'request', public.bulk_deck_analysis_request_json(request_row),
      'usage', public.bulk_deck_analysis_usage_snapshot_for(
        current_user_id, current_session_id
      ),
      'is_duplicate', true
    );
  end if;

  select * into entitlement
  from public.bulk_deck_analysis_resolve_entitlement(
    current_user_id, current_session_id
  ) limit 1;
  if not entitlement.eligible then
    raise exception 'BULK_ANALYSIS_INELIGIBLE' using errcode = 'P0001';
  end if;

  insert into public.bulk_deck_analysis_monthly_usage (user_id, usage_month)
  values (current_user_id, current_month)
  on conflict on constraint bulk_deck_analysis_monthly_usage_pkey do nothing;

  select * into aggregate_row
  from public.bulk_deck_analysis_monthly_usage usage
  where usage.user_id = current_user_id and usage.usage_month = current_month
  for update;

  perform public.bulk_deck_analysis_expire_stale(current_user_id, current_month);

  select * into request_row
  from public.bulk_deck_analysis_requests requests
  where requests.user_id = current_user_id
    and requests.idempotency_key = p_idempotency_key
  for update;
  if request_row.id is not null then
    if request_row.request_fingerprint <> p_request_fingerprint then
      raise exception 'BULK_ANALYSIS_IDEMPOTENCY_CONFLICT' using errcode = 'P0001';
    end if;
    return jsonb_build_object(
      'request', public.bulk_deck_analysis_request_json(request_row),
      'usage', public.bulk_deck_analysis_usage_snapshot_for(
        current_user_id, current_session_id
      ),
      'is_duplicate', true
    );
  end if;

  select count(*)::integer into active_count
  from public.bulk_deck_analysis_requests requests
  where requests.user_id = current_user_id
    and requests.reservation_month = current_month
    and requests.status = 'processing'
    and requests.expires_at > clock_timestamp();

  if not entitlement.is_unlimited
     and aggregate_row.completed_count + active_count >= entitlement.monthly_limit then
    raise exception 'BULK_ANALYSIS_LIMIT_REACHED' using errcode = 'P0001';
  end if;

  insert into public.bulk_deck_analysis_requests (
    user_id, idempotency_key, request_fingerprint, reservation_month,
    entitlement_source, resolved_limit, is_unlimited,
    reserved_at, expires_at
  ) values (
    current_user_id, p_idempotency_key, p_request_fingerprint, current_month,
    entitlement.entitlement_source, entitlement.monthly_limit,
    entitlement.is_unlimited, clock_timestamp(),
    clock_timestamp() + interval '15 minutes'
  ) returning * into request_row;

  return jsonb_build_object(
    'request', public.bulk_deck_analysis_request_json(request_row),
    'usage', public.bulk_deck_analysis_usage_snapshot_for(
      current_user_id, current_session_id
    ),
    'is_duplicate', false
  );
end;
$function$

