CREATE OR REPLACE FUNCTION public.update_connected_commander_damage(p_session_id uuid, p_source_participant_id uuid, p_delta integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  target_participant_id uuid;
  damage_record public.connected_match_commander_damage;
begin
  if current_user_id is null then
    raise exception 'Authentication is required to update commander damage.'
      using errcode = '28000';
  end if;

  if not exists (
    select 1
    from public.connected_match_sessions sessions
    where sessions.id = p_session_id
      and sessions.status = 'active'
  ) then
    raise exception 'This Connected Match is not active.'
      using errcode = '22023';
  end if;

  select participants.id
  into target_participant_id
  from public.connected_match_participants participants
  where participants.session_id = p_session_id
    and participants.user_id = current_user_id
    and participants.terminal_state = 'active';

  if target_participant_id is null then
    raise exception 'You are not an active participant in this Connected Match.'
      using errcode = '42501';
  end if;

  if p_source_participant_id = target_participant_id then
    raise exception 'Commander damage source must be another player.'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.connected_match_participants source
    where source.session_id = p_session_id
      and source.id = p_source_participant_id
  ) then
    raise exception 'Commander damage source is not part of this Connected Match.'
      using errcode = '22023';
  end if;

  insert into public.connected_match_commander_damage (
    session_id,
    target_participant_id,
    source_participant_id,
    damage
  )
  values (
    p_session_id,
    target_participant_id,
    p_source_participant_id,
    greatest(0, least(p_delta, 1000))
  )
  on conflict (session_id, target_participant_id, source_participant_id)
  do update set
    damage = greatest(0, least(connected_match_commander_damage.damage + p_delta, 1000))
  returning *
  into damage_record;

  update public.connected_match_participants
  set
    last_seen_at = now(),
    reconnect_until = now() + interval '30 minutes'
  where id = target_participant_id;

  return row_to_json(damage_record)::jsonb;
end;
$function$

