CREATE OR REPLACE FUNCTION public.update_store_checkin_lfg(p_store_id uuid, p_looking_for_commander_game boolean, p_commander_game_status text DEFAULT NULL::text, p_decks_brought jsonb DEFAULT NULL::jsonb, p_visit_reason text DEFAULT NULL::text)
 RETURNS TABLE(ok boolean, store_id uuid, looking_for_commander_game boolean, commander_game_status text, decks_brought jsonb, visit_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_user_id uuid := auth.uid();
  checkin_date date := (now() at time zone 'utc')::date;
  active_store_id uuid;
  next_commander_status text;
  next_decks_brought jsonb;
  next_visit_reason text;
  updated_checkin record;
begin
  if current_user_id is null then
    raise exception 'Authentication is required to update store check-in status.'
      using errcode = '28000';
  end if;

  select stores.id
  into active_store_id
  from public.stores
  where stores.id = p_store_id
    and stores.is_public
    and stores.is_active;

  if active_store_id is null then
    raise exception 'This store check-in link is no longer active.'
      using errcode = 'P0002';
  end if;

  if p_looking_for_commander_game then
    next_commander_status := coalesce(p_commander_game_status, 'looking');
  else
    next_commander_status := 'not_looking';
  end if;

  if next_commander_status not in ('not_looking', 'looking', 'seated', 'full', 'finished') then
    raise exception 'Invalid Commander game status.'
      using errcode = '22023';
  end if;

  if p_decks_brought is not null and jsonb_typeof(p_decks_brought) <> 'array' then
    raise exception 'decks_brought must be a JSON array.'
      using errcode = '22023';
  end if;

  if p_visit_reason is not null
    and p_visit_reason not in ('general', 'commander', 'event', 'trade', 'shopping', 'pickup', 'learn_to_play', 'other') then
    raise exception 'Invalid visit reason.'
      using errcode = '22023';
  end if;

  update public.store_checkins
  set
    looking_for_commander_game = p_looking_for_commander_game,
    commander_game_status = next_commander_status,
    decks_brought = coalesce(p_decks_brought, store_checkins.decks_brought),
    visit_reason = coalesce(p_visit_reason, store_checkins.visit_reason)
  where store_checkins.store_id = active_store_id
    and store_checkins.user_id = current_user_id
    and store_checkins.check_in_date = checkin_date
  returning
    store_checkins.store_id,
    store_checkins.looking_for_commander_game,
    store_checkins.commander_game_status,
    store_checkins.decks_brought,
    store_checkins.visit_reason
  into updated_checkin;

  if updated_checkin.store_id is null then
    return query
    select
      false,
      active_store_id,
      false,
      'not_looking'::text,
      '[]'::jsonb,
      'general'::text;
    return;
  end if;

  return query
  select
    true,
    updated_checkin.store_id,
    updated_checkin.looking_for_commander_game,
    updated_checkin.commander_game_status,
    updated_checkin.decks_brought,
    updated_checkin.visit_reason;
end;
$function$
